<?php
namespace Tests\Feature;
use App\Models\{JpHold,Unlock,UnlockParticipation,User}; use App\Services\UnlockParticipationService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class UnlockFulfillmentTest extends TestCase { use RefreshDatabase;
 protected function setUp():void{parent::setUp();config()->set('unlocks.jp_commitments_enabled',true);}
 public function test_confirmation_is_idempotent_and_expiry_releases_only_unconfirmed_hold():void{$u=User::factory()->create();$x=$this->unlock(['confirmation_deadline'=>now()->addHour()]);$p=UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>$u->id,'status'=>UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION,'confirmation_requested_at'=>now()]);app(UnlockParticipationService::class)->confirm($x,$u);app(UnlockParticipationService::class)->confirm($x,$u);$this->assertSame(UnlockParticipation::CONFIRMED,$p->fresh()->status);$v=User::factory()->create();$q=UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>$v->id,'status'=>UnlockParticipation::UNLOCKED_PENDING_CONFIRMATION]);JpHold::create(['user_id'=>$v->id,'unlock_participation_id'=>$q->id,'amount'=>5,'status'=>JpHold::HELD,'held_at'=>now()]);$x->update(['confirmation_deadline'=>now()->subMinute()]);app(UnlockParticipationService::class)->processDeadlines();app(UnlockParticipationService::class)->processDeadlines();$this->assertSame(UnlockParticipation::EXPIRED,$q->fresh()->status);$this->assertSame(JpHold::RELEASED,JpHold::where('unlock_participation_id',$q->id)->sole()->status);}
 public function test_confirmed_no_show_forfeits_once_without_bonus():void{$u=User::factory()->create();$x=$this->unlock(['fulfillment_ends_at'=>now()->subMinute()]);$p=UnlockParticipation::create(['unlock_id'=>$x->id,'user_id'=>$u->id,'status'=>UnlockParticipation::CONFIRMED,'confirmed_at'=>now()->subHour()]);JpHold::create(['user_id'=>$u->id,'unlock_participation_id'=>$p->id,'amount'=>5,'status'=>JpHold::HELD,'held_at'=>now()]);app(UnlockParticipationService::class)->processDeadlines();app(UnlockParticipationService::class)->processDeadlines();$this->assertSame(UnlockParticipation::NO_SHOW,$p->fresh()->status);$this->assertSame(JpHold::FORFEITED,JpHold::sole()->status);$this->assertDatabaseHas('reward_transactions',['forfeited_jp_hold_id'=>JpHold::sole()->id,'amount'=>-5,'source'=>'unlock_forfeiture']);$this->assertDatabaseCount('reward_transactions',1);}
 private function unlock(array $o=[]):Unlock{return Unlock::create(array_merge(['title'=>'U'.uniqid(),'slug'=>'u'.uniqid(),'origin'=>'JAKAWI','type'=>'BENEFIT','minimum_commitments'=>1,'free_user_eligible'=>true,'member_eligible'=>true,'jp_deposit'=>0,'jp_completion_bonus'=>0,'status'=>Unlock::UNLOCKED],$o));}}
